WITH cleaned AS (SELECT id, session_id, event_type, duration_sec, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time FROM web_events WHERE event_time > TIMESTAMP '2023-06-24 03:00:00' AND page IS NOT NULL), joined AS (SELECT e.id, e.session_id, e.duration_sec, s.country, s.browser FROM cleaned e INNER JOIN sessions s ON e.session_id = s.id WHERE s.customer_id IS NOT NULL), enriched AS (SELECT a.id, a.session_id, a.country, a.browser, p.device, p.browser AS session_browser FROM joined a LEFT JOIN sessions p ON a.session_id = p.id), with_dims AS (SELECT src.*, s.browser AS session_browser_2 FROM enriched src INNER JOIN sessions s ON src.session_id = s.id), report AS (SELECT id, session_id, country, browser, device, session_browser, session_browser_2, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'EXTENDED' WHEN device RLIKE '^(mobile)$' THEN 'CORE' ELSE 'GROUP_A' END AS device_zone FROM with_dims) SELECT id, country, browser, device, session_browser_2, device_zone FROM report ORDER BY id DESC;
